/*
 * test_render.cpp — emeraldwf_render_frame golden tests (part 02, headless).
 *
 * For each engine x {active, inactive} x {windowed, maximized} at client 400x300 with default settings:
 *   - call emeraldwf_render_frame, save PNG;
 *   - compare against tests/golden/<engine>_<state>_<mode>.png (first-run goldens generated by
 * make_goldens.cpp);
 *   - structural asserts: surface size == D7 formula, surface non-empty.
 *
 * NOTE (spec, part 02 "Out of scope"): until part 03 lands, the tobj / button_region fields are filled with a
 * minimal layout (all items state 3), so goldens are structure-only; part 06 regenerates them.
 */
#include <gtest/gtest.h>

#include <unistd.h>

#include <cstring>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include <cairo.h>
#include <gdk-pixbuf/gdk-pixbuf.h>

#include "emerald-engine.hpp"
#include "emerald-layout.hpp"
#include "emerald-settings.hpp"
// Review R2: fixture paths forwarded by meson (configure_file) — the
///proc/self/exe heuristic broke for out-of-tree builds, where the engine
// .so's live in <builddir>/engines, not <srcroot>/build/engines.
#include "test-paths.h"

using namespace wf::emeraldwf;
namespace fs = std::filesystem;

namespace
{
std::string project_root()
{
    return EMERALDWF_TEST_SOURCE_ROOT;
}

fs::path golden_dir()
{
    return fs::path(project_root()) / "tests" / "golden";
}

std::string defaults_dir()
{
    return project_root() + "/third_party/emerald/defaults";
}

// Fill a DecorContext with a minimal layout: all items state 3 (not
// present), no buttons. This matches the spec's "until 03 lands" note.
DecorContext make_ctx(const ThemeSettings & ts, bool active, bool maximized)
{
    window_settings *ws = ts.ws();
    const int client_w = 400, client_h = 300;

    DecorContext ctx;
    ctx.client_width  = client_w;
    ctx.client_height = client_h;
    ctx.width  = frame_width(*ws, client_w);
    ctx.height = frame_height(*ws, client_w, client_h);
    ctx.active = active;
    ctx.fs     = active ? ts.fs_active() : ts.fs_inactive();
    ctx.state  = maximized ?
        (EWS_MAXIMIZED_HORIZONTALLY | EWS_MAXIMIZED_VERTICALLY) :
        0;
    ctx.actions = EWA_CLOSE | EWA_MAXIMIZE | EWA_MINIMIZE;

    // minimal layout: all items state 3
    for (int i = 0; i < 11; i++)
    {
        ctx.tobj_item_state[i] = 3;
    }

    for (int i = 0; i < 9; i++)
    {
        ctx.button_states[i] = 0;
    }

    return ctx;
}

bool surfaces_equal(cairo_surface_t *a, cairo_surface_t *b)
{
    if (cairo_image_surface_get_width(a) !=
        cairo_image_surface_get_width(b))
    {
        return false;
    }

    if (cairo_image_surface_get_height(a) !=
        cairo_image_surface_get_height(b))
    {
        return false;
    }

    const int w = cairo_image_surface_get_width(a);
    const int h = cairo_image_surface_get_height(a);
    const int stride_a = cairo_image_surface_get_stride(a);
    const int stride_b = cairo_image_surface_get_stride(b);
    const unsigned char *da =
        (const unsigned char*)cairo_image_surface_get_data(a);
    const unsigned char *db =
        (const unsigned char*)cairo_image_surface_get_data(b);

    for (int y = 0; y < h; y++)
    {
        const unsigned char *ra = da + y * stride_a;
        const unsigned char *rb = db + y * stride_b;
        for (int x = 0; x < w; x++)
        {
            if (std::memcmp(ra + x * 4, rb + x * 4, 4) != 0)
            {
                return false;
            }
        }
    }

    return true;
}

bool load_png(cairo_surface_t **out, const fs::path & file)
{
    GError *err = nullptr;
    GdkPixbuf *pixbuf = gdk_pixbuf_new_from_file(file.c_str(), &err);
    if (err)
    {
        g_error_free(err);
        return false;
    }

    const int w = gdk_pixbuf_get_width(pixbuf);
    const int h = gdk_pixbuf_get_height(pixbuf);
    cairo_surface_t *surf = cairo_image_surface_create(CAIRO_FORMAT_ARGB32, w, h);
    cairo_t *cr = cairo_create(surf);
    gdk_cairo_set_source_pixbuf(cr, pixbuf, 0, 0);
    cairo_set_operator(cr, CAIRO_OPERATOR_SOURCE);
    cairo_paint(cr);
    cairo_destroy(cr);
    g_object_unref(pixbuf);
    *out = surf;
    return true;
}

bool surface_nonempty(cairo_surface_t *surf)
{
    const int w = cairo_image_surface_get_width(surf);
    const int h = cairo_image_surface_get_height(surf);
    const int stride = cairo_image_surface_get_stride(surf);
    const unsigned char *data =
        (const unsigned char*)cairo_image_surface_get_data(surf);
    for (int y = 0; y < h; y++)
    {
        for (int x = 0; x < w; x++)
        {
            const unsigned char *p = data + y * stride + x * 4;
            if (p[0] || p[1] || p[2] || p[3])
            {
                return true;
            }
        }
    }

    return false;
}

class RenderTest : public ::testing::Test
{
  public:
    void SetUp() override
    {
        ThemeSettings ts;
        ASSERT_TRUE(ts.load(
            project_root() + "/third_party/emerald/defaults/settings.ini",
            project_root() + "/third_party/emerald/defaults/theme"));
        ts_ = std::make_shared<const ThemeSettings>(std::move(ts));
    }

    std::shared_ptr<const ThemeSettings> ts_;
};

static const char *kEngines[] = {"legacy", "truglass", "vrunner", "oxygen",
    "zootreeves", "pixmap", "line"};

TEST_F(RenderTest, Structural)
{
    for (const char *engine : kEngines)
    {
        for (bool active : {true, false})
        {
            for (bool maximized : {true, false})
            {
                std::string mode  = maximized ? "max" : "win";
                std::string state = active ? "active" : "inactive";
                DecorContext ctx  = make_ctx(*ts_, active, maximized);

                // reload the engine for each combination
                ASSERT_TRUE(emerald_engine_load(
                    engine, EMERALDWF_TEST_ENGINE_DIR)) <<
                    engine;
                // Allocate the engine's private ws/fs for this ws.
                emerald_engine_init_engine(ts_->ws());

                cairo_surface_t *surf = emeraldwf_render_frame(*ts_, ctx);
                ASSERT_NE(surf, nullptr) <<
                    "engine=" << engine << " state=" << state <<
                    " mode=" << mode;

                // D7 formula
                EXPECT_EQ(cairo_image_surface_get_width(surf), ctx.width);
                EXPECT_EQ(cairo_image_surface_get_height(surf), ctx.height);
                EXPECT_TRUE(surface_nonempty(surf)) <<
                    "engine=" << engine << " state=" << state <<
                    " mode=" << mode;

                // golden
                fs::path golden =
                    golden_dir() /
                    (std::string(engine) + "_" + state + "_" + mode +
                        ".png");
                if (fs::exists(golden))
                {
                    cairo_surface_t *g = nullptr;
                    ASSERT_TRUE(load_png(&g, golden)) <<
                        "failed to load golden " << golden;
                    EXPECT_TRUE(surfaces_equal(surf, g)) <<
                        "engine=" << engine << " state=" << state <<
                        " mode=" << mode << " differs from golden";
                    if (g)
                    {
                        cairo_surface_destroy(g);
                    }
                }

                cairo_surface_destroy(surf);
                emerald_engine_unload();
            }
        }
    }
}

TEST_F(RenderTest, MaximizedDiffersForZootreeves)
{
    // zootreeves has enable_maximised_colors; with default settings it is
    // false, so windowed vs maximized should still differ (corners are
    // cleared when maximized).
    DecorContext win = make_ctx(*ts_, true, false);
    DecorContext max = make_ctx(*ts_, true, true);

    ASSERT_TRUE(emerald_engine_load("zootreeves",
        EMERALDWF_TEST_ENGINE_DIR));
    emerald_engine_init_engine(ts_->ws());
    cairo_surface_t *sw = emeraldwf_render_frame(*ts_, win);
    cairo_surface_t *sm = emeraldwf_render_frame(*ts_, max);
    ASSERT_NE(sw, nullptr);
    ASSERT_NE(sm, nullptr);

    // The D7 sizes differ between windowed and maximized (frame height
    // depends on stretch_sides + client_h), so the surfaces are not
    // directly comparable. Instead assert the structural sizes.
    EXPECT_EQ(cairo_image_surface_get_width(sw), win.width);
    EXPECT_EQ(cairo_image_surface_get_height(sw), win.height);
    EXPECT_EQ(cairo_image_surface_get_width(sm), max.width);
    EXPECT_EQ(cairo_image_surface_get_height(sm), max.height);

    cairo_surface_destroy(sw);
    cairo_surface_destroy(sm);
    emerald_engine_unload();
}

TEST_F(RenderTest, MaximizedCropShrinksSurface)
{
    // Finding 19: maximized + both crop options off → the surface is the
    // CROPPED frame (client + titlebar strip only), not the full-extent
    // frame. With emerald defaults the shadow spread is 0, so both-off
    // crops exactly the border spaces off all sides.
    DecorContext max = make_ctx(*ts_, true, true);
    max.maximized_borders = false;
    max.maximized_shadows = false;

    ASSERT_TRUE(emerald_engine_load("zootreeves",
        EMERALDWF_TEST_ENGINE_DIR));
    emerald_engine_init_engine(ts_->ws());
    cairo_surface_t *sm = emeraldwf_render_frame(*ts_, max);
    ASSERT_NE(sm, nullptr);

    window_settings *ws = ts_->ws();
    EXPECT_EQ(cairo_image_surface_get_width(sm),
        max.width - ws->left_space - ws->right_space);
    EXPECT_EQ(cairo_image_surface_get_height(sm),
        max.height - ws->top_space - ws->bottom_space);
    // Cropped frame = client + titlebar strip.
    EXPECT_EQ(cairo_image_surface_get_height(sm),
        300 + ws->titlebar_height);

    cairo_surface_destroy(sm);
    emerald_engine_unload();
}

// ── Finding 19c: shadows-on + borders-off must NOT draw the border ─────────
//
// A maximized window with borders off keeps ONLY the shadow spread as its
// side margin. The engine draws the border at the inner edge of that shadow
// region (full-extent [spread, spread+ext)); if the render translate shifts
// the surface by the BORDER part (instead of only the shadow part, which is
// 0 here), the border lands INSIDE the surface — "checking draw shadows
// draws borders too". The shadow margin of the two renders must be
// pixel-identical; a wrong translate makes it contain the border instead.

TEST_F(RenderTest, MaximizedBordersOffShadowsOn_NoBorderInShadow)
{
    // zootreeves draws the maximized border only when the theme's
    // show_border_maximised is true (the default theme sets it false), so
    // build a temp theme flipping that one line — with the pixmaps copied.
    const auto defaults =
        fs::path(project_root()) / "third_party" / "emerald" / "defaults";
    const auto tmp = fs::temp_directory_path() / "emeraldwf-test-theme";
    std::error_code ec;
    fs::remove_all(tmp, ec);
    fs::create_directories(tmp, ec);
    for (auto & entry : fs::directory_iterator(defaults / "theme"))
    {
        if (entry.is_regular_file())
        {
            fs::copy_file(entry.path(), tmp / entry.path().filename(),
                fs::copy_options::overwrite_existing, ec);
        }
    }

    ASSERT_FALSE(ec);
    {
        std::ifstream in((tmp / "theme.ini").string());
        std::string content((std::istreambuf_iterator<char>(in)),
            std::istreambuf_iterator<char>());
        ASSERT_NE(
            content.find("show_border_maximised=false"),
            std::string::npos);
        content.replace(content.find("show_border_maximised=false"),
            std::string("show_border_maximised=false").size(),
            "show_border_maximised=true");
        // Opaque frame colors (zootreeves' maximized defaults are alpha
        // 0.5 — the opaque-pixel scan needs a real border; with
        // enable_maximised_colors (default true) the *_maximised colors
        // are the ones used for a maximized window).
        const auto pos = content.find("show_border_maximised=true");
        content.insert(pos +
            std::string("show_border_maximised=true").size(),
            "\ninner_maximised=#ffffff\ninner_maximised_alpha=1.0\n"
            "outer_maximised=#ffffff\nouter_maximised_alpha=1.0");
        std::ofstream out((tmp / "theme.ini").string());
        out << content;
    }

    ThemeSettings ts;
    ASSERT_TRUE(ts.load((defaults / "settings.ini").string(),
        tmp.string(), "zootreeves"));
    window_settings *ws = ts.ws();
    const int shadow    = 10; // give the theme a bigger shadow spread
    ws->left_space   += shadow;
    ws->right_space  += shadow;
    ws->top_space    += shadow;
    ws->bottom_space += shadow;

    ASSERT_TRUE(emerald_engine_load("zootreeves",
        EMERALDWF_TEST_ENGINE_DIR));
    emerald_engine_init_engine(ws);

    const int ext_l   = ws->win_extents.left;
    const int extra_l = ws->extra_extents.left;
    const int spread  = ws->left_space - ext_l - extra_l; // after the +10

    // Borders OFF, shadows ON → margin = shadow spread only.
    DecorContext max = make_ctx(ts, true, true);
    max.maximized_borders = false;
    max.maximized_shadows = true;
    cairo_surface_t *sm = emeraldwf_render_frame(ts, max);
    ASSERT_NE(sm, nullptr);

    // Surface width = client + 2·spread (no border part).
    EXPECT_EQ(cairo_image_surface_get_width(sm),
        400 + 2 * spread);

    // Control: borders ON → the full margin (spread + border) is kept.
    max.maximized_borders = true;
    cairo_surface_t *sw = emeraldwf_render_frame(ts, max);
    ASSERT_NE(sw, nullptr);
    EXPECT_EQ(cairo_image_surface_get_width(sw),
        400 + 2 * (spread + ext_l + extra_l));

    // The borders-OFF shadow margin [0, spread) must contain NO border.
    // The top border band [st, st+border_t) is removed from the surface and
    // the content below it reflows UP by border_t, so:
    // rows [0, st)          — above the top band: pixel-identical to the
    // borders-ON surface (same shadow, same place);
    // rows [st, st+tb)      — the left column next to the titlebar:
    // sm(x, y) == sw(x, y + border_t).
    // With the pre-19c code the whole surface was translated by the border
    // part, so the [0, spread) columns contained the border instead of the
    // shadow — "checking draw shadows draws borders too" — caught by (a).
    // A reflow-less crop (surface just truncated) would fail (b): the
    // titlebar would be clipped short and the margin rows would not line up.
    {
        const unsigned char *do_ =
            cairo_image_surface_get_data(sm);
        const unsigned char *d1_ =
            cairo_image_surface_get_data(sw);
        const int stride0 = cairo_image_surface_get_stride(sm);
        const int stride1 = cairo_image_surface_get_stride(sw);
        const int st = ws->top_space - ws->win_extents.top -
            ws->extra_extents.top; // top shadow spread
        const int border_t = ws->win_extents.top +
            2 * ws->extra_extents.top;

        // (a) above the top band: identical shadow columns
        bool identical = true;
        for (int y = 0; y < st && identical; ++y)
        {
            for (int x = 0; x < spread; ++x)
            {
                if (std::memcmp(do_ + y * stride0 + x * 4,
                    d1_ + y * stride1 + x * 4, 4) != 0)
                {
                    identical = false;
                    break;
                }
            }
        }

        EXPECT_TRUE(identical) <<
            "borders-off shadow margin above the top band differs "
            "(surface translated by the border part — border inside "
            "the shadow)";

        // (b) the border band is removed and the content reflows up
        bool reflow = true;
        for (int y = st; y < st + ws->titlebar_height && reflow; ++y)
        {
            for (int x = 0; x < spread; ++x)
            {
                if (std::memcmp(do_ + y * stride0 + x * 4,
                    d1_ + (y + border_t) * stride1 + x * 4,
                    4) != 0)
                {
                    reflow = false;
                    break;
                }
            }
        }

        EXPECT_TRUE(reflow) <<
            "borders-off top border band not reflowed (content below "
            "the removed band must shift up by the border thickness)";
    }

    cairo_surface_destroy(sm);
    cairo_surface_destroy(sw);
    emerald_engine_unload();
    ws->left_space   -= shadow;
    ws->right_space  -= shadow;
    ws->top_space    -= shadow;
    ws->bottom_space -= shadow;
    std::error_code ec2;
    fs::remove_all(tmp, ec2);
}

// ── Finding 19c: the remaining two crop states map 1:1 onto the
// full-extent frame (the border/shadow band removed per option, content
// reflowed) ─────────────────────────────────────────────────────────────────
TEST_F(RenderTest, MaximizedCropMatrix_PixelCorrespondence)
{
    const auto defaults =
        fs::path(project_root()) / "third_party" / "emerald" / "defaults";
    const auto tmp = fs::temp_directory_path() / "emeraldwf-test-theme2";
    std::error_code ec;
    fs::remove_all(tmp, ec);
    fs::create_directories(tmp, ec);
    for (auto & entry : fs::directory_iterator(defaults / "theme"))
    {
        if (entry.is_regular_file())
        {
            fs::copy_file(entry.path(), tmp / entry.path().filename(),
                fs::copy_options::overwrite_existing, ec);
        }
    }

    ASSERT_FALSE(ec);
    {
        std::ifstream in((tmp / "theme.ini").string());
        std::string content((std::istreambuf_iterator<char>(in)),
            std::istreambuf_iterator<char>());
        const auto pos = content.find("show_border_maximised=false");
        ASSERT_NE(pos, std::string::npos);
        content.replace(pos, std::string("show_border_maximised=false").size(),
            "show_border_maximised=true");
        std::ofstream out((tmp / "theme.ini").string());
        out << content;
    }

    ThemeSettings ts;
    ASSERT_TRUE(ts.load((defaults / "settings.ini").string(),
        tmp.string(), "zootreeves"));
    window_settings *ws = ts.ws();
    const int shadow    = 10;
    ws->left_space   += shadow;
    ws->right_space  += shadow;
    ws->top_space    += shadow;
    ws->bottom_space += shadow;

    ASSERT_TRUE(emerald_engine_load("zootreeves",
        EMERALDWF_TEST_ENGINE_DIR));
    emerald_engine_init_engine(ws);

    const int ext_l    = ws->win_extents.left;
    const int extra_l  = ws->extra_extents.left;
    const int spread   = ws->left_space - ext_l - extra_l;
    const int ext_t    = ws->win_extents.top;
    const int extra_t  = ws->extra_extents.top;
    const int spread_t = ws->top_space - ext_t - extra_t;

    // Full-extent reference (both options on = no crop).
    DecorContext ref = make_ctx(ts, true, true);
    ref.maximized_borders = true;
    ref.maximized_shadows = true;
    cairo_surface_t *sw = emeraldwf_render_frame(ts, ref);
    ASSERT_NE(sw, nullptr);

    // Shadows OFF, borders ON → margin = the border part; the shadow
    // spread is cropped from the OUTER edge, so the surface origin is the
    // full-extent point (spread, spread_t) and the border sits FLUSH at
    // the surface edge: surface (x, y) = full (x + spread, y + spread_t).
    {
        DecorContext c = ref;
        c.maximized_shadows = false;
        cairo_surface_t *ss = emeraldwf_render_frame(ts, c);
        ASSERT_NE(ss, nullptr);
        EXPECT_EQ(cairo_image_surface_get_width(ss),
            400 + 2 * (ext_l + extra_l));

        const unsigned char *d0 = cairo_image_surface_get_data(ss);
        const unsigned char *d1 = cairo_image_surface_get_data(sw);
        const int s0   = cairo_image_surface_get_stride(ss);
        const int s1   = cairo_image_surface_get_stride(sw);
        const int rows = cairo_image_surface_get_height(ss);
        bool flush     = true;
        for (int y = 0; y < rows && flush; ++y)
        {
            for (int x = 0; x < ext_l + extra_l; ++x)
            {
                if (std::memcmp(
                    d0 + y * s0 + x * 4,
                    d1 + (y + spread_t) * s1 + (x + spread) * 4,
                    4) != 0)
                {
                    flush = false;
                    break;
                }
            }
        }

        EXPECT_TRUE(flush) <<
            "borders-on/shadows-off margin does not carry the border "
            "flush at the surface edge (full-extent (x+spread, "
            "y+spread_t))";
        cairo_surface_destroy(ss);
    }

    // BOTH OFF → margin = titlebar strip only; the surface's top-left is
    // the frame's INNER corner: surface (x, y) = full (x + left_space,
    // y + top_space) — border and shadow gone, titlebar at the top.
    {
        DecorContext c = ref;
        c.maximized_borders = false;
        c.maximized_shadows = false;
        cairo_surface_t *bo = emeraldwf_render_frame(ts, c);
        ASSERT_NE(bo, nullptr);
        EXPECT_EQ(cairo_image_surface_get_width(bo), 400);
        EXPECT_EQ(cairo_image_surface_get_height(bo),
            300 + ws->titlebar_height);

        const unsigned char *d0 = cairo_image_surface_get_data(bo);
        const unsigned char *d1 = cairo_image_surface_get_data(sw);
        const int s0 = cairo_image_surface_get_stride(bo);
        const int s1 = cairo_image_surface_get_stride(sw);
        bool inner   = true;
        for (int y = 0; y < ws->titlebar_height && inner; ++y)
        {
            for (int x = 0; x < 400; ++x)
            {
                if (std::memcmp(
                    d0 + y * s0 + x * 4,
                    d1 + (y + spread_t + ext_t + extra_t) * s1 +
                    (x + spread + ext_l + extra_l) * 4, 4) != 0)
                {
                    inner = false;
                    break;
                }
            }
        }

        EXPECT_TRUE(inner) <<
            "both-off surface top row is not the full-extent titlebar "
            "row (border+shadow crop must reflow the titlebar to the "
            "surface top)";
        cairo_surface_destroy(bo);
    }

    cairo_surface_destroy(sw);
    emerald_engine_unload();
    ws->left_space   -= shadow;
    ws->right_space  -= shadow;
    ws->top_space    -= shadow;
    ws->bottom_space -= shadow;
    fs::remove_all(tmp);
}

// ── Button hover/press surface states (part 06 regression) ──────────────────
//
// The node sets ctx.button_states[b] |= IN_EVENT_WINDOW on hover and
// |= (IN_EVENT_WINDOW | PRESSED_EVENT_WINDOW) while a button is held;
// emeraldwf_render_frame must then select the matching surface column
// (get_b_state → S_ACTIVE_HOVER / S_ACTIVE_PRESS). Without that wiring the
// buttons rendered identically in every state ("in original emerald buttons
// used to change color when hovered").
TEST_F(RenderTest, ButtonHoverAndPressSurfaceStates)
{
    ASSERT_TRUE(emerald_engine_load(
        "vrunner", EMERALDWF_TEST_ENGINE_DIR));
    emerald_engine_init_engine(ts_->ws());

    DecorContext ctx = make_ctx(*ts_, true, false);
    static EmeraldLayout layout;
    layout.title_text_width_ = 100;
    layout.build(*ts_, ctx);

    const auto & r = ctx.button_region[B_T_MINIMIZE];
    ASSERT_GT(r.base_x2, r.base_x1) << "minimize button not placed";
    ASSERT_GT(r.base_y2, r.base_y1);

    auto render_with = [&] (int st) -> cairo_surface_t*
    {
        for (int i = 0; i < 9; i++)
        {
            ctx.button_states[i] = 0;
        }

        ctx.button_states[B_T_MINIMIZE] = st;
        return emeraldwf_render_frame(*ts_, ctx);
    };

    cairo_surface_t *normal = render_with(0);
    cairo_surface_t *hover = render_with(IN_EVENT_WINDOW);
    cairo_surface_t *press =
        render_with(IN_EVENT_WINDOW | PRESSED_EVENT_WINDOW);
    ASSERT_NE(normal, nullptr);
    ASSERT_NE(hover, nullptr);
    ASSERT_NE(press, nullptr);

    auto region_differs = [&] (cairo_surface_t *a, cairo_surface_t *b)
    {
        const int stride_a = cairo_image_surface_get_stride(a);
        const int stride_b = cairo_image_surface_get_stride(b);
        const unsigned char *da =
            (const unsigned char*)cairo_image_surface_get_data(a);
        const unsigned char *db =
            (const unsigned char*)cairo_image_surface_get_data(b);
        for (int y = r.base_y1; y < r.base_y2; ++y)
        {
            for (int x = r.base_x1; x < r.base_x2; ++x)
            {
                if (std::memcmp(
                    da + y * stride_a + x * 4,
                    db + y * stride_b + x * 4, 4) != 0)
                {
                    return true;
                }
            }
        }

        return false;
    };

    EXPECT_TRUE(region_differs(normal, hover)) <<
        "hover state renders the same pixels as the normal state";
    EXPECT_TRUE(region_differs(normal, press)) <<
        "pressed state renders the same pixels as the normal state";

    cairo_surface_destroy(normal);
    cairo_surface_destroy(hover);
    cairo_surface_destroy(press);
    emerald_engine_unload();
}

// ── HOME isolation helper (missing-pixmap tests) ───────────────────────────
//
// The vendored engine resolves its .so via $HOME/.emerald/engines first
// (emerald_engine_load) and its pixmap PNGs via the HARDCODED
// $HOME/.emerald/theme/ (make_filename in libengine/emerald.c). A
// deterministic missing-pixmap scenario must therefore control HOME: a
// temp dir that contains ONLY the engine .so (→ the engine loads and
// ThemeSettings::load() wires its load_engine_settings() to the test
// theme), and no theme dir (→ every pixmap load yields a surface in an
// ERROR state, CAIRO_STATUS_FILE_NOT_FOUND — note: NOT NULL).
class HomeIsolate
{
  public:
    explicit HomeIsolate(const char *engine)
    {
        old_home_   = std::getenv("HOME");
        saved_home_ = old_home_ ? old_home_ : "";
        home_ = fs::temp_directory_path() /
            (fs::path("emeraldwf-homeiso") / std::to_string(::getpid()));
        fs::create_directories(home_ / ".emerald" / "engines");
        const auto so =
            fs::path(EMERALDWF_TEST_ENGINE_DIR) /
            ("lib" + std::string(engine) + ".so");
        std::error_code ec;
        fs::create_symlink(so, home_ / ".emerald" / "engines" / so.filename(),
            ec);
        EXPECT_TRUE(!ec) << "engine symlink: " << ec.message();
        ::setenv("HOME", home_.c_str(), 1);
    }

    ~HomeIsolate()
    {
        ::setenv("HOME", saved_home_.c_str(), 1);
        std::error_code ec;
        fs::remove_all(home_, ec);
    }

  private:
    const char *old_home_ = nullptr;
    std::string saved_home_;
    fs::path home_;
};

// ── zootreeves + missing pixmap PNGs (part 06 regression: "no decorations
// around window") ────────────────────────────────────────────────────────────
//
// The user's theme enables zootreeves' pixmap parts (pixmaps_titlebar_enabled
// = true) but the theme ships no pixmaps/*.png. cairo_image_surface_create_
// from_png() then yields NULL and cairo_set_source_surface() on it is a
// no-op: the titlebar fill silently paints nothing, and because the theme's
// frame body colors are alpha-0 the WHOLE frame rendered fully transparent.
// The port guard in zootreeves.c (fill_rounded_square: surface == NULL →
// gradient fallback) must make the titlebar visible again.
TEST_F(RenderTest, ZootreevesMissingPixmaps_TitlebarStillDrawn)
{
    // HOME isolation: the engine .so must be found under the temp HOME so
    // load() wires zootreeves' load_engine_settings() to this theme, while
    // the (hardcoded) ~/.emerald/theme/ stays empty → missing pixmaps.
    HomeIsolate home("zootreeves");

    // Build a theme that mirrors the user's: default theme.ini with the
    // zootreeves pixmap parts enabled, and NO pixmaps directory.
    fs::path theme_dir = fs::temp_directory_path() /
        (fs::path("emeraldwf-zoot-nopix") / std::to_string(::getpid()));
    fs::create_directories(theme_dir / "theme");
    {
        std::ifstream in(
            fs::path(defaults_dir()) / "theme" / "theme.ini");
        std::ofstream out(theme_dir / "theme" / "theme.ini");
        std::string line;
        bool inserted = false;
        std::string section;
        while (std::getline(in, line))
        {
            // Part 07: the theme's own engine wins — point the copied
            // theme at zootreeves (the default says vrunner).
            if ((line.rfind("[", 0) == 0) && (line.back() == ']'))
            {
                section = line.substr(1, line.size() - 2);
            }

            if ((section == "engine") && (line.rfind("engine=", 0) == 0))
            {
                line = "engine=zootreeves";
            }

            out << line << "\n";
            if (!inserted && (line == "[zootreeves_settings]"))
            {
                out << "pixmaps_titlebar_enabled=true\n" <<
                    "pixmaps_titlebarpart_enabled=true\n" <<
                    "pixmaps_buttonpart_enabled=true\n";
                inserted = true;
            }
        }

        ASSERT_TRUE(inserted);
    }

    ThemeSettings ts;
    ASSERT_TRUE(ts.load(
        defaults_dir() + "/settings.ini", (theme_dir / "theme").string(),
        "zootreeves"));
    // ts.load() already loaded zootreeves and called its
    // load_engine_settings() with the keyfile above — re-running
    // emerald_engine_init_engine() would wipe the theme's pixmap flags
    // and make this test pass for the wrong reason.
    EXPECT_EQ(ts.engine(), "zootreeves");

    DecorContext ctx = make_ctx(ts, true, false);
    cairo_surface_t *surf = emeraldwf_render_frame(ts, ctx);
    ASSERT_NE(surf, nullptr);

    // The titlebar band (frame-local y ≈ 12..34 for the default theme) must
    // contain visible pixels — before the guard the whole surface was
    // transparent (opaque == 0).
    const int stride = cairo_image_surface_get_stride(surf);
    const unsigned char *data =
        (const unsigned char*)cairo_image_surface_get_data(surf);
    int opaque = 0;
    for (int y = 12; y < 34; ++y)
    {
        for (int x = 0; x < cairo_image_surface_get_width(surf); ++x)
        {
            if (data[y * stride + x * 4 + 3] > 8)
            {
                ++opaque;
            }
        }
    }

    EXPECT_GT(opaque, 0) <<
        "titlebar band is fully transparent (missing-pixmap no-op)";

    cairo_surface_destroy(surf);
    emerald_engine_unload();
    fs::remove_all(theme_dir);
}

// ── zootreeves + missing pixmap PNGs: BUTTONS (part 06 finding 10 regression
// "zootreeves shows no buttons") ─────────────────────────────────────────────
//
// Same missing-pixmap condition as the test above, with a nastier
// consequence: cairo_image_surface_create_from_png() does NOT return NULL
// for a missing file — it returns a surface in an ERROR state
// (CAIRO_STATUS_FILE_NOT_FOUND). The original `surface == NULL` guard in
// zootreeves' fill_rounded_square() therefore never fired; the engine used
// the errored surface as a source and cairo_set_source_surface() put the
// CONTEXT into an error state, after which every draw on the context is a
// silent no-op. The rest of the frame, the title text and ALL the buttons
// disappeared — while the button REGIONS (layout) stayed correct, which is
// exactly the reported symptom: the hover cursor changes over the button
// area, but nothing is drawn. The guard must check
// cairo_surface_status(), and this test asserts the full frame content:
// titlebar band + every button cell.
TEST_F(RenderTest, ZootreevesMissingPixmaps_ButtonsAndBorderDrawn)
{
    HomeIsolate home("zootreeves");

    // Default theme.ini with the zootreeves pixmap parts enabled (no
    // pixmaps.*.png shipped) AND the shadow disabled, so that the only
    // opaque content on the surface is the engine draw itself.
    const fs::path theme_dir = fs::temp_directory_path() /
        (fs::path("emeraldwf-zoot-nopix2") / std::to_string(::getpid()));
    fs::create_directories(theme_dir / "theme");
    {
        std::ifstream in(fs::path(defaults_dir()) / "theme" / "theme.ini");
        std::ofstream out(theme_dir / "theme" / "theme.ini");
        std::string line;
        bool inserted = false;
        std::string section;
        while (std::getline(in, line))
        {
            // Part 07: the theme's own engine wins — point the copied
            // theme at zootreeves (the default says vrunner).
            if ((line.rfind("[", 0) == 0) && (line.back() == ']'))
            {
                section = line.substr(1, line.size() - 2);
            }

            if ((section == "engine") && (line.rfind("engine=", 0) == 0))
            {
                line = "engine=zootreeves";
            }

            if (line.rfind("shadow_radius=", 0) == 0)
            {
                line = "shadow_radius=0";
            }

            out << line << "\n";
            // Insert AFTER the group header (a key before the first group
            // makes g_key_file_load_from_file() reject the whole file:
            // "Key file does not start with a group").
            if (!inserted && (line == "[zootreeves_settings]"))
            {
                out << "pixmaps_titlebar_enabled=true\n" <<
                    "pixmaps_titlebarpart_enabled=true\n" <<
                    "pixmaps_buttonpart_enabled=true\n";
                inserted = true;
            }
        }

        ASSERT_TRUE(inserted);
    }

    ThemeSettings ts;
    ASSERT_TRUE(ts.load(
        defaults_dir() + "/settings.ini", (theme_dir / "theme").string(),
        "zootreeves"));
    // ts.load() already dlopen'd zootreeves (via $HOME/.emerald/engines)
    // and called its load_engine_settings() with the keyfile above. Do NOT
    // call emerald_engine_init_engine() again: init re-allocates the
    // engine's private settings with defaults, wiping the theme's
    // [zootreeves_settings] (including the pixmap flags this test
    // exercises) and leaving the pixmap surfaces NULL.
    EXPECT_EQ(ts.engine(), "zootreeves");

    // Real layout (make_ctx's minimal one hides all items): the default
    // titlebar layout I(30):T:N(2)X(2)C: places close/min/max.
    DecorContext ctx = make_ctx(ts, true, false);
    EmeraldLayout layout;
    layout.title_text_width_ = 120;
    layout.build(ts, ctx);

    int visible_buttons = 0;
    for (int i = 0; i < B_T_COUNT; ++i)
    {
        if ((ctx.tobj_item_state[i] != 3) &&
            (ctx.button_region[i].base_x2 > ctx.button_region[i].base_x1))
        {
            ++visible_buttons;
        }
    }

    ASSERT_GE(visible_buttons, 3) << "expected close/min/max buttons";

    cairo_surface_t *surf = emeraldwf_render_frame(ts, ctx);
    ASSERT_NE(surf, nullptr);

    const int stride = cairo_image_surface_get_stride(surf);
    const unsigned char *data =
        (const unsigned char*)cairo_image_surface_get_data(surf);
    const int w = cairo_image_surface_get_width(surf);
    const int h = cairo_image_surface_get_height(surf);
    auto opaque_in = [&] (int x1, int y1, int x2, int y2)
    {
        int n = 0;
        for (int y = std::max(0, y1); y < std::min(h, y2); ++y)
        {
            for (int x = std::max(0, x1); x < std::min(w, x2); ++x)
            {
                if (data[y * stride + x * 4 + 3] > 8)
                {
                    ++n;
                }
            }
        }

        return n;
    };

    // 1) titlebar band: span the full width on the button row (buttons sit
    // inside the band, so the band region includes the title text area).
    {
        const auto & r = ctx.button_region[0];
        EXPECT_GT(opaque_in(0, r.base_y1, r.base_x1, r.base_y2), 0) <<
            "titlebar band transparent (context died in the engine draw)";
    }

    // 2) every visible button cell must be painted — the user's exact
    // symptom: the regions exist for hit-testing but draw nothing.
    for (int i = 0; i < B_T_COUNT; ++i)
    {
        if (ctx.tobj_item_state[i] == 3)
        {
            continue;
        }

        const auto & r = ctx.button_region[i];
        EXPECT_GT(opaque_in(r.base_x1, r.base_y1, r.base_x2, r.base_y2), 0) <<
            "button " << i << " at (" << r.base_x1 << "," << r.base_y1 <<
            ")-(" << r.base_x2 << "," << r.base_y2 << ") drew nothing";
    }

    cairo_surface_destroy(surf);
    emerald_engine_unload();
    fs::remove_all(theme_dir);
}
}
